mapper.select:
select `id`,`city`, `longtitle`, `shorttitle`,
`header_image` headerImage,`poster_image` posterImage,`meeting_point` meetingPoint,`days`,`departdate`,`status`,`price`,`body`,
`trip_content` tripContent,`expense_detail` expenseDetail,`note`,ctime,uptime
from tlx_activity
where 1=1

    and `status` = #{activity.status}


    and `city` = #{activity.city}

order by ctime desc limit #{start}, #{size}
